'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var Float64Array = require( '@stdlib/array/float64' );
var Int32Array = require( '@stdlib/array/int32' );
var format = require( '@stdlib/string/format' );
var pkg = require( './../package.json' ).name;
var dsyconvfRook = require( './../lib' );


// FUNCTIONS //

/**
* Creates a bounded conversion/reversion benchmark.
*
* @private
* @param {PositiveInteger} N - matrix order
* @param {string} uplo - stored triangle
* @returns {Function} benchmark function
*/
function createBenchmark( N, uplo ) {
	var IPIV;
	var A;
	var E;
	var i;
	var j;

	A = new Float64Array( N*N );
	E = new Float64Array( N );
	IPIV = new Int32Array( N );
	for ( i = 0; i < N; i++ ) {
		IPIV[ i ] = i + 1;
		for ( j = 0; j < N; j++ ) {
			A[ (i*N)+j ] = i + j + 1.0;
		}
	}
	// The first two rows form a 2x2 block with distinct negative pivots:
	IPIV[ 0 ] = -1;
	IPIV[ 1 ] = -2;
	return benchmark;

	/**
	* Benchmark function.
	*
	* @private
	* @param {Benchmark} b - benchmark instance
	*/
	function benchmark( b ) {
		var info;
		var i;

		b.tic();
		for ( i = 0; i < b.iterations; i++ ) {
			info = dsyconvfRook( 'row-major', uplo, 'convert', N, A, N, E, IPIV );
			if ( info !== 0 ) {
				b.fail( 'should return a success status code' );
				break;
			}
			info = dsyconvfRook( 'row-major', uplo, 'revert', N, A, N, E, IPIV );
			if ( info !== 0 ) {
				b.fail( 'should return a success status code' );
				break;
			}
		}
		b.toc();
		if (
			A[ 1 ] !== 2.0 ||
			A[ N ] !== 2.0 ||
			IPIV[ 0 ] !== -1 ||
			IPIV[ 1 ] !== -2
		) {
			b.fail( 'should preserve factor storage after a complete cycle' );
		}
		if (
			( uplo === 'upper' && E[ 1 ] !== 2.0 ) ||
			( uplo === 'lower' && E[ 0 ] !== 2.0 )
		) {
			b.fail( 'should extract the known off-diagonal block value' );
		}
		b.pass( 'benchmark finished' );
		b.end();
	}
}


// MAIN //

/**
* Main execution sequence.
*
* @private
*/
function main() {
	var options;
	var sizes;
	var uplos;
	var name;
	var i;
	var j;

	options = {
		'iterations': 1000,
		'repeats': 2
	};
	sizes = [ 8, 32 ];
	uplos = [ 'upper', 'lower' ];
	for ( i = 0; i < sizes.length; i++ ) {
		for ( j = 0; j < uplos.length; j++ ) {
			name = format( '%s:triangle=%s:N=%d', pkg, uplos[ j ], sizes[ i ] );
			bench( name, options, createBenchmark( sizes[ i ], uplos[ j ] ) );
		}
	}
}

main();
